1	import { test, before, after } from 'node:test';
2	import assert from 'node:assert/strict';
3	import vm from 'node:vm';
4	import { startServer, removeDataDir, type StartedServer } from '../testing/server.ts';
5	
6	// 这些测试不在浏览器里跑，而是启动真实服务、GET / 取出页面里的内联脚本原文，
7	// 再放入带极简 DOM / 可控 fetch 的 vm 沙箱执行。被测脚本与线上页面逐字一致，
8	// 同时每个请求的成功、失败、返回先后都可以由测试精确控制。
9	
10	let server: StartedServer;
11	let pageScript: string;
