13	before(async () => {
14	  server = await startServer();
15	  const res = await fetch(`${server.origin}/`);
16	  assert.equal(res.status, 200);
17	  const html = await res.text();
18	  const start = html.indexOf('<script>');
19	  const end = html.lastIndexOf('</script>');
20	  assert.notEqual(start, -1);
21	  assert.ok(end > start);
22	  pageScript = html.slice(start + '<script>'.length, end);
23	});
