30	interface El {
31	  tagName: string;
32	  className: string;
33	  hidden: boolean;
34	  value: string;
35	  dateTime: string;
36	  children: El[];
37	  text: string | null;
38	  textContent: string;
39	  listeners: Record<string, Array<(event: unknown) => unknown>>;
40	  append(...nodes: El[]): void;
41	  replaceChildren(...nodes: El[]): void;
42	  addEventListener(type: string, fn: (event: unknown) => unknown): void;
43	  reset(): void;
44	}
45	
46	function makeElement(tag: string): El {
47	  const node = {
48	    tagName: tag.toUpperCase(),
49	    className: '',
50	    hidden: false,
51	    value: '',
52	    dateTime: '',
53	    children: [],
54	    text: null as string | null,
55	    listeners: {} as Record<string, Array<(event: unknown) => unknown>>,
56	    append(...nodes: El[]): void {
57	      this.children.push(...nodes);
58	    },
59	    replaceChildren(...nodes: El[]): void {
60	      this.children = [...nodes];
61	    },
62	    addEventListener(type: string, fn: (event: unknown) => unknown): void {
63	      (this.listeners[type] ??= []).push(fn);
64	    },
65	    reset(): void {},
66	  };
67	  Object.defineProperty(node, 'textContent', {
68	    get(this: any): string {
69	      return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join('');
70	    },
71	    set(this: any, value: unknown): void {
72	      this.text = String(value);
73	    },
74	  });
75	  return node as El;
76	}
77	
78	interface Gate {
79	  promise: Promise<unknown>;
80	  resolve: (value: unknown) => void;
81	  reject: (error: Error) => void;
82	}
83	
84	function gate(): Gate {
85	  let resolve!: (value: unknown) => void;
86	  let reject!: (error: Error) => void;
87	  const promise = new Promise<unknown>((res, rej) => {
88	    resolve = res;
89	    reject = rej;
90	  });
91	  return { promise, resolve, reject };
92	}
93	
94	function jsonResponse(status: number, body: unknown): any {
95	  return {
96	    ok: status >= 200 && status < 300,
97	    status,
98	    json: async () => body,
99	  };
100	}
101	
102	function brokenJsonResponse(status = 201): any {
103	  return {
104	    ok: status >= 200 && status < 300,
105	    status,
106	    json: async () => {
107	      throw new SyntaxError('响应体不是有效 JSON');
108	    },
109	  };
110	}
111	
112	const flush = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 0));
113	
114	let ideaSeq = 0;
115	function makeIdea(partial: Record<string, unknown> = {}): Record<string, unknown> {
116	  ideaSeq += 1;
117	  return {
118	    id: `id-${ideaSeq}`,
119	    title: `标题 ${ideaSeq}`,
120	    description: `详细说明 ${ideaSeq}`,
121	    scenario: '',
122	    createdAt: '2026-01-01T00:00:00.000Z',
123	    ...partial,
124	  };
125	}
126	
127	const SUCCESS_TEXT = '提交成功，你的意见已保存。';
128	const EMPTY_TEXT = '还没有意见记录。';
129	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
130	const NETWORK_ERROR_TEXT = '网络错误，提交未成功，请重试。';
131	const SUBMIT_FAILED_TEXT = '提交失败，请稍后重试。';
132	
133	class Harness {
134	  els: Record<string, El> = {};
135	  gets: Gate[] = [];
136	  getsIssued = 0;
137	  posts: Gate[] = [];
138	  postsIssued = 0;
139	  postBodies: unknown[] = [];
140	
141	  constructor(script: string) {
142	    const byId: Map<string, El> = new Map();
143	    const register = (id: string, tag: string, hidden = false): El => {
144	      const node = makeElement(tag);
145	      node.hidden = hidden;
146	      byId.set(id, node);
147	      this.els[id] = node;
148	      return node;
149	    };
150	    const form = register('idea-form', 'form');
151	    const titleInput = register('f-title', 'input');
152	    const descInput = register('f-desc', 'textarea');
153	    const scenarioInput = register('f-scenario', 'textarea');
154	    register('error', 'p', true);
155	    register('success', 'p', true);
156	    register('empty', 'p', true);
157	    register('ideas', 'div');
158	    form.reset = (): void => {
159	      titleInput.value = '';
160	      descInput.value = '';
161	      scenarioInput.value = '';
162	    };
163	    const documentMock = {
164	      getElementById: (id: string): El => byId.get(id)!,
165	      createElement: (tag: string): El => makeElement(tag),
166	    };
167	    const fetchMock = (url: unknown, init?: { method?: string; body?: unknown }): Promise<unknown> => {
168	      const method = init?.method ?? 'GET';
169	      const pending = gate();
170	      if (method === 'POST') {
171	        this.posts.push(pending);
172	        this.postsIssued += 1;
173	        this.postBodies.push(init?.body);
174	      } else {
175	        this.gets.push(pending);
176	        this.getsIssued += 1;
177	      }
178	      return pending.promise;
179	    };
180	    const context = vm.createContext({ console, document: documentMock, fetch: fetchMock });
181	    vm.runInContext(script, context, { filename: 'inline-page-script.js' });
182	  }
183	
184	  setForm(values: { title?: string; description?: string; scenario?: string }): void {
185	    if (values.title !== undefined) this.els['f-title'].value = values.title;
186	    if (values.description !== undefined) this.els['f-desc'].value = values.description;
187	    if (values.scenario !== undefined) this.els['f-scenario'].value = values.scenario;
188	  }
189	
190	  // 模拟真实用户输入：赋值并触发 input 事件（setForm 不触发事件，只用于布置初始状态）
191	  edit(id: string, value: string): void {
192	    const el = this.els[id];
193	    el.value = value;
194	    for (const fn of el.listeners.input ?? []) fn({ target: el });
195	  }
196	
197	  // 触发表单 submit 监听器，返回监听器（async 函数）的 Promise
198	  submit(): Promise<unknown> {
199	    const handler = this.els['idea-form'].listeners.submit[0];
200	    return handler({ preventDefault(): void {} });
201	  }
202	
203	  articles(): El[] {
204	    return this.els.ideas.children.filter((node) => node.tagName === 'ARTICLE');
205	  }
206	
207	  titles(): string[] {
208	    return this.articles().map((article) => article.children.find((n) => n.tagName === 'H3')!.textContent);
209	  }
210	}
211	
212	function findScenario(article: El): El | undefined {
213	  return article.children.find(
214	    (node) =>
215	      node.tagName === 'P' &&
216	      node.children.some((child) => child.tagName === 'STRONG' && child.textContent === '使用场景：'),
217	  );
218	}
219	
220	// 校验一条已渲染的意见与原记录逐字段对应：标题、详细说明、非空使用场景、提交时间
221	function assertArticleMatches(article: El, idea: Record<string, unknown>): void {
222	  const heading = article.children.find((n) => n.tagName === 'H3')!;
223	  assert.equal(heading.textContent, idea.title);
224	  const description = article.children.find((n) => n.tagName === 'P' && n.children.length === 0)!;
225	  assert.equal(description.textContent, idea.description);
226	  const scenarioNode = findScenario(article);
227	  const expectsScenario =
228	    typeof idea.scenario === 'string' && idea.scenario.trim().length > 0;
229	  assert.equal(
230	    Boolean(scenarioNode),
231	    expectsScenario,
232	    `使用场景展示与否应与记录一致：${String(idea.scenario)}`,
233	  );
234	  if (expectsScenario) {
235	    const span = scenarioNode!.children.find((n) => n.tagName === 'SPAN')!;
236	    assert.equal(span.textContent, idea.scenario);
237	  }
238	  const time = article.children.find((n) => n.tagName === 'TIME')!;
239	  assert.equal(time.dateTime, idea.createdAt);
240	}
241	
242	test('打开首页即请求首次列表；加载尚未结束时不显示“还没有意见记录”', () => {
243	  const h = new Harness(pageScript);
244	  assert.equal(h.gets.length, 1);
