261	  assert.equal(h.els.error.hidden, true);
262	  assert.equal(h.els['f-title'].value, '');
263	  assert.equal(h.els['f-desc'].value, '');
264	  assert.equal(h.els['f-scenario'].value, '');
265	  assert.deepEqual(h.titles(), ['我的意见']);
266	  // 首次列表仍在等待，不能把等待误报成没有记录
